CREATE TABLE `mock_exam_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` bigint(20) unsigned NOT NULL,
  `source_question_id` int(10) unsigned DEFAULT NULL,
  `topic_id` smallint(5) unsigned DEFAULT NULL,
  `question_text` text NOT NULL,
  `question_type` varchar(20) NOT NULL DEFAULT 'mcq',
  `difficulty` varchar(20) DEFAULT NULL,
  `choices` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`choices`)),
  `explanation` text DEFAULT NULL,
  `points` smallint(5) unsigned NOT NULL DEFAULT 1,
  `sort_order` smallint(5) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `image_path` varchar(255) DEFAULT NULL,
  `table_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`table_data`)),
  PRIMARY KEY (`id`),
  KEY `mock_exam_items_exam_id_sort_order_index` (`exam_id`,`sort_order`),
  CONSTRAINT `mock_exam_items_exam_id_foreign` FOREIGN KEY (`exam_id`) REFERENCES `mock_exams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
